<template><div><PageHeader title="Settings" description="Configure your organization, brand, notifications and security."><template #actions><button class="btn primary" @click="save">Save changes</button></template></PageHeader><div class="settings-grid"><div class="card settings-nav"><a href="#general" class="active">General</a><a href="#branding">Branding</a><a href="#users">Users</a><a href="#roles">Roles & permissions</a><a href="#notifications">Notifications</a><a href="#certificate">Certificate</a><a href="#security">Security</a><a href="#audit">Audit logs</a></div><div class="card"><div class="form-section" id="general"><h3>General</h3><p>Organization profile and regional defaults.</p><div class="form-grid"><div class="field"><label>Organization name</label><input class="input" v-model="form.org"></div><div class="field"><label>Support email</label><input class="input" v-model="form.email"></div><div class="field"><label>Country</label><select class="select"><option>United Arab Emirates</option><option>India</option></select></div><div class="field"><label>Timezone</label><select class="select"><option>Asia/Dubai</option><option>Asia/Kolkata</option></select></div><div class="field"><label>Currency</label><select class="select"><option>AED</option><option>USD</option><option>INR</option></select></div></div></div><div class="form-section" id="branding"><h3>Branding</h3><p>Customize the visual identity used in the application and certificates.</p><div class="form-grid"><div class="field"><label>Logo</label><button class="btn secondary">Upload logo</button></div><div class="field"><label>Primary color</label><input class="input" v-model="form.color"></div></div></div><div class="form-section" id="certificate"><h3>Certificate</h3><p>Default certificate configuration.</p><div class="form-grid"><div class="field"><label>Certificate prefix</label><input class="input" value="TRN"></div><div class="field"><label>Verification URL</label><input class="input" value="https://trainingos.demo/verify-certificate"></div></div></div><div class="form-section" id="security"><h3>Security</h3><p>Protect access to your workspace.</p><div class="notice-list"><div class="notice-item"><div class="notice-copy"><strong>Two-factor authentication</strong><p>Require 2FA for organization admins.</p></div><label class="check"><input type="checkbox" checked> Enabled</label></div><div class="notice-item"><div class="notice-copy"><strong>Session management</strong><p>Users can review and revoke active sessions.</p></div><button class="btn secondary small">View sessions</button></div></div></div></div></div></div></template>
<script setup lang="ts">import {reactive} from 'vue';import PageHeader from '../components/PageHeader.vue';import {useToast} from '../composables/useToast';const form=reactive({org:'Nexa Training Academy',email:'ops@nexa.example',color:'#2563EB'});const {push}=useToast();function save(){push('Organization settings saved.')}</script>
